// Package config loads the add-on options that the Home Assistant Supervisor
// writes to /data/options.json from the schema in my_velo/config.yaml.
// The path is passed in by the caller (see cmd/myvelo, flag -options).
package config

import (
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"log/slog"
	"os"
)

// Options mirrors the "options"/"schema" section of my_velo/config.yaml.
type Options struct {
	LogLevel    string `json:"log_level"`
	MapProvider string `json:"map_provider"`
	MapTilerKey string `json:"maptiler_key"`
}

// Defaults returns the options used when no options file exists, e.g. during
// local development.
func Defaults() Options {
	return Options{LogLevel: "info", MapProvider: "osm"}
}

// Load reads the options file. A missing file yields the defaults; any other
// error is returned because a broken configuration must not be ignored.
func Load(path string) (Options, error) {
	opts := Defaults()
	raw, err := os.ReadFile(path)
	if errors.Is(err, fs.ErrNotExist) {
		return opts, nil
	}
	if err != nil {
		return opts, fmt.Errorf("read options: %w", err)
	}
	if err := json.Unmarshal(raw, &opts); err != nil {
		return opts, fmt.Errorf("parse options %s: %w", path, err)
	}
	return opts, nil
}

// SlogLevel maps the add-on log level to a slog level.
func (o Options) SlogLevel() slog.Level {
	switch o.LogLevel {
	case "debug":
		return slog.LevelDebug
	case "warning":
		return slog.LevelWarn
	case "error":
		return slog.LevelError
	default:
		return slog.LevelInfo
	}
}
